/**
 * Renderiza el icono vectorial adecuado según el slug, nombre del producto, adición o categoría.
 * Si no se pasa o no existe, usa IconToolsKitchen2 como fallback seguro.
 */
export function FoodIcon({ name = "", category = "", size = 20, stroke = 1.75, className = "", ...props }) {
  const rawKey = String(name || category || "").trim().toLowerCase();

  // 1. Coincidencia directa por slug exacto en el mapa
  if (ICON_MAP[rawKey]) {
    const Component = ICON_MAP[rawKey];
    return <Component size={size} stroke={stroke} className={className} {...props} />;
  }

  // 2. Coincidencia semántica inteligente (búsqueda de palabras clave)
  const k = `${String(name || "")} ${String(category || "")}`.toLowerCase();

  if (k.includes("hambur")) {
    return <IconBurger size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("perro") || k.includes("hot dog") || k.includes("hotdog")) {
    return <IconHotDog size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("salchicha") || k.includes("chorizo") || k.includes("sausage")) {
    return <IconSausage size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("salchipapa") || k.includes("papa") || k.includes("frita") || k.includes("casco")) {
    return <IconFrenchFries size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("acompa") || k.includes("guarnic") || k.includes("side")) {
    return <IconAcompanamientos size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("toci") || k.includes("bacon")) {
    return <IconBaconStrip size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("queso") || k.includes("cheddar") || k.includes("mozzarella")) {
    return <IconCheese size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("pizza")) {
    return <IconPizza size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("bebida") || k.includes("gaseosa") || k.includes("refresco") || k.includes("sprite") || k.includes("coca") || k.includes("pepsi") || k.includes("quatro") || k.includes("colombiana") || k.includes("uva") || k.includes("jugo")) {
    return <IconCup size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("agua") || k.includes("cristal") || k.includes("botella")) {
    return <IconBottle size={size} stroke={stroke} className={className} {...props} />;
  }
  // Eventos y Promociones Streamline
  if (k.includes("fuego") || k.includes("flame") || k.includes("fire") || k.includes("burger fest") || k.includes("festival")) {
    return <StreamlineFlame size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("2x1") || k.includes("dos por uno") || k.includes("dos x uno")) {
    return <StreamlineDoubleBurger size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("flash") || k.includes("relampago") || k.includes("relámpago") || k.includes("rayo")) {
    return <StreamlineBolt size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("descuento") || k.includes("discount") || k.includes("off") || k.includes("ticket") || k.includes("cupon") || k.includes("cupón")) {
    return <StreamlineDiscountTicket size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("combo")) {
    return <IconComboBurgerDrink size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("regalo") || k.includes("gift")) {
    return <StreamlineGiftBox size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("corona") || k.includes("crown") || k.includes("edicion especial") || k.includes("edición especial")) {
    return <StreamlineCrown size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("calendar") || k.includes("calendario") || k.includes("fecha") || k.includes("evento")) {
    return <StreamlineCalendarCheck size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("party") || k.includes("fiesta") || k.includes("celebracion") || k.includes("celebración") || k.includes("popper")) {
    return <StreamlinePartyPopper size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("rocket") || k.includes("cohete") || k.includes("lanzamiento")) {
    return <StreamlineRocket size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("carne") || k.includes("patty") || k.includes("res") || k.includes("pollo") || k.includes("alita") || k.includes("nugget") || k.includes("broaster")) {
    return <IconMeat size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("huevo")) {
    return <IconEggFried size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("champi") || k.includes("hongo")) {
    return <IconMushroom size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("aguacate") || k.includes("guacamole")) {
    return <IconAvocado size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("jalap") || k.includes("picante") || k.includes("aji")) {
    return <IconPepper size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("salsa") || k.includes("bbq") || k.includes("ajo") || k.includes("tartara") || k.includes("mayo") || k.includes("ketchup")) {
    return <IconBottleFilled size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("cebolla") || k.includes("onion")) {
    return <IconOnion size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("tomate") || k.includes("tomato")) {
    return <IconTomato size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("lechuga") || k.includes("lettuce")) {
    return <IconLettuce size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("ensalada") || k.includes("veggie")) {
    return <IconSalad size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("zanahoria") || k.includes("carrot")) {
    return <IconCarrot size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("pan") || k.includes("brioche")) {
    return <IconBread size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("manzana")) {
    return <IconApple size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("postre") || k.includes("torta") || k.includes("pastel")) {
    return <IconCake size={size} stroke={stroke} className={className} {...props} />;
  }
  if (k.includes("helado")) {
    return <IconIceCream size={size} stroke={stroke} className={className} {...props} />;
  }

  // Emblema institucional Chazin Food (último check para no sobreescribir iconos de comida)
  if (k.includes("chazin") || k.includes("emblema")) {
    return <IconChazinEmblem size={size} className={className} {...props} />;
  }

  // 3. Fallback limpio por defecto
  return <IconToolsKitchen2 size={size} stroke={stroke} className={className} {...props} />;
}

export default FoodIcon;

/**
 * Contenedor suave (Soft Badge / Chip) con diseño profesional de comida rápida
 */
export function FoodIconBadge({
  name = "",
  category = "",
  size = "md",
  iconSize,
  isSelected = false,
  className = "",
  children,
  ...props
}) {
  const theme = getFoodColorTheme(name || category);

  const sizeClasses = {
    xs: "w-6 h-6 rounded-lg",
    sm: "w-8 h-8 rounded-xl",
    md: "w-10 h-10 rounded-2xl",
    lg: "w-12 h-12 sm:w-14 sm:h-14 rounded-2xl",
    xl: "w-16 h-16 rounded-3xl"
  }[size] || "w-10 h-10 rounded-2xl";

  const defaultIconSizes = {
    xs: 13,
    sm: 16,
    md: 20,
    lg: 26,
    xl: 32
  }[size] || 20;

  const actualIconSize = iconSize || defaultIconSizes;

  if (isSelected) {
    return (
      <div
        className={`flex items-center justify-center shrink-0 bg-white dark:bg-gray-900 text-[#f05454] dark:text-red-400 shadow-md transition-all ${sizeClasses} ${className}`}
        {...props}
      >
        <FoodIcon name={name} category={category} size={actualIconSize} stroke={2} />
        {children}
      </div>
    );
  }

  return (
    <div
      className={`flex items-center justify-center shrink-0 border transition-all ${sizeClasses} ${theme.bg} ${theme.text} ${theme.border} shadow-xs ${className}`}
      {...props}
    >
      <FoodIcon name={name} category={category} size={actualIconSize} stroke={1.8} />
      {children}
    </div>
  );
}

/**
 * ═════════════════════════════════════════════════════════════════════════════
 * CONFIGURADOR INTELIGENTE DE BADGES DE EVENTO (STREAMLINE FAST-FOOD THEME)
/**
 * Sanitiza textos de productos y eventos removiendo cualquier emoji unicode
 * para garantizar una interfaz 100% limpia con iconografía vectorial SVG profesional.
 */
export const stripEmojis = (str) => {
  if (!str || typeof str !== "string") return "";
  return str
    .replace(/\p{Extended_Pictographic}/gu, "")
    .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, "")
    .replace(/^\s*[-–—:]\s*/, "")
    .replace(/\s{2,}/g, " ")
    .trim();
};

/**
 * ═════════════════════════════════════════════════════════════════════════════
 * CONFIGURACIÓN DE BADGES DINÁMICOS PARA EVENTOS ESPECIALES
 * Determina el icono, gradiente, resplandor, copy y paleta visual según el tipo de evento
 * ═════════════════════════════════════════════════════════════════════════════
 */
export function getEventBadgeConfig(event, product = null) {
  if (!event) return null;

  const rawIcon = String(event.icono || "").toLowerCase().trim();
  const rawType = String(event.tipoEvento || event.tipo || "").toLowerCase().trim();
  const rawName = String(event.nombreEvento || event.nombre || "").toLowerCase().trim();
  const combined = `${rawIcon} ${rawType} ${rawName}`;
  const cleanName = stripEmojis(event.nombreEvento || event.nombre || "");

  // 1. EDICIÓN LIMITADA / BURGER FEST / FESTIVAL GOURMET
  if (
    rawIcon === "fire" ||
    rawIcon === "flame" ||
    rawType.includes("edicion") ||
    rawType.includes("limitada") ||
    combined.includes("burger fest") ||
    combined.includes("festival")
  ) {
    return {
      key: "festival",
      Icon: StreamlineFlame,
      iconSlug: "fire",
      label: combined.includes("burger fest") ? "BURGER FEST" : "EDICIÓN LIMITADA",
      fullLabel: cleanName || "Edición Limitada",
      gradient: "from-amber-500 via-orange-500 to-red-600",
      border: "border-amber-300/40",
      glow: "shadow-[0_4px_16px_rgba(245,158,11,0.45)]",
      textColor: "text-white",
      pillBg: "bg-amber-100 dark:bg-amber-950/60 text-amber-800 dark:text-amber-300 border-amber-200 dark:border-amber-900/60",
      accentColor: "#f59e0b"
    };
  }

  // 2. PROMOCIÓN 2X1
  if (
    rawIcon === "2x1" ||
    rawType.includes("2x1") ||
    combined.includes("2x1") ||
    combined.includes("dos por uno")
  ) {
    return {
      key: "2x1",
      Icon: StreamlineDoubleBurger,
      iconSlug: "2x1",
      label: "PROMO 2X1",
      fullLabel: cleanName || "Jueves 2x1",
      gradient: "from-indigo-600 via-purple-600 to-pink-600",
      border: "border-purple-300/40",
      glow: "shadow-[0_4px_16px_rgba(168,85,247,0.45)]",
      textColor: "text-white",
      pillBg: "bg-purple-100 dark:bg-purple-950/60 text-purple-800 dark:text-purple-300 border-purple-200 dark:border-purple-900/60",
      accentColor: "#a855f7"
    };
  }

  // 3. DESCUENTOS (% OFF o DESCUENTO GENERAL)
  if (
    rawIcon === "discount" ||
    rawType.includes("descuento") ||
    event.descuento ||
    combined.includes("off") ||
    combined.includes("fin de semana")
  ) {
    const pct = event.descuento ? Number(event.descuento) : null;
    const label = pct ? `-${pct}% OFF` : (combined.includes("15%") ? "-15% OFF" : (combined.includes("20%") ? "-20% OFF" : "DESCUENTO"));
    return {
      key: "discount",
      Icon: StreamlineDiscountTicket,
      iconSlug: "discount",
      label,
      fullLabel: cleanName || "Descuento Exclusivo",
      gradient: "from-emerald-500 via-teal-500 to-cyan-600",
      border: "border-emerald-300/40",
      glow: "shadow-[0_4px_16px_rgba(160,185,129,0.45)]",
      textColor: "text-white",
      pillBg: "bg-emerald-100 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300 border-emerald-200 dark:border-emerald-900/60",
      accentColor: "#10b981"
    };
  }

  // 4. PROMO RELÁMPAGO / FLASH SALE / PROMOCIÓN PRECIO
  if (
    rawIcon === "flash" ||
    rawType.includes("precio") ||
    combined.includes("relampago") ||
    combined.includes("relámpago") ||
    combined.includes("flash")
  ) {
    return {
      key: "flash",
      Icon: StreamlineBolt,
      iconSlug: "flash",
      label: "PROMO FLASH",
      fullLabel: cleanName || "Promo Relámpago",
      gradient: "from-amber-400 via-yellow-500 to-orange-500",
      border: "border-yellow-200/60",
      glow: "shadow-[0_4px_16px_rgba(234,179,8,0.5)]",
      textColor: "text-gray-950",
      pillBg: "bg-amber-100 dark:bg-amber-950/60 text-amber-900 dark:text-amber-300 border-amber-200 dark:border-amber-900/60",
      accentColor: "#eab308"
    };
  }

  // 5. COMBOS ESPECIALES / FESTIVOS
  if (
    rawIcon === "gift" ||
    rawType.includes("combo") ||
    combined.includes("combo") ||
    combined.includes("pareja")
  ) {
    return {
      key: "combo",
      Icon: StreamlineGiftBox,
      iconSlug: "gift",
      label: "COMBO FESTIVO",
      fullLabel: cleanName || "Combo Especial",
      gradient: "from-fuchsia-600 via-purple-600 to-indigo-600",
      border: "border-fuchsia-300/40",
      glow: "shadow-[0_4px_16px_rgba(217,70,239,0.45)]",
      textColor: "text-white",
      pillBg: "bg-fuchsia-100 dark:bg-fuchsia-950/60 text-fuchsia-800 dark:text-fuchsia-300 border-fuchsia-200 dark:border-fuchsia-900/60",
      accentColor: "#d946ef"
    };
  }

  // 6. TOPPINGS GRATIS / AÑADIR INSUMOS
  if (
    rawIcon === "bacon" ||
    rawType.includes("insumo") ||
    combined.includes("topping") ||
    combined.includes("tocineta")
  ) {
    return {
      key: "toppings",
      Icon: IconBaconStrip,
      iconSlug: "bacon",
      label: "+ TOPPING GRATIS",
      fullLabel: cleanName || "Festival de Toppings",
      gradient: "from-rose-500 via-red-500 to-amber-500",
      border: "border-rose-300/40",
      glow: "shadow-[0_4px_16px_rgba(244,63,94,0.45)]",
      textColor: "text-white",
      pillBg: "bg-rose-100 dark:bg-rose-950/60 text-rose-800 dark:text-rose-300 border-rose-200 dark:border-rose-900/60",
      accentColor: "#f43f5e"
    };
  }

  // 7. CUALQUIER OTRO SLUG DE AVAILABLE_FOOD_SLUGS (Hamburguesa, Perro, Papas, etc.)
  const matchedFood = AVAILABLE_FOOD_SLUGS.find((s) => s.slug === rawIcon);
  if (matchedFood) {
    return {
      key: matchedFood.slug,
      Icon: matchedFood.icon,
      iconSlug: matchedFood.slug,
      label: matchedFood.label.toUpperCase(),
      fullLabel: cleanName || matchedFood.label,
      gradient: "from-purple-600 via-indigo-600 to-blue-600",
      border: "border-purple-300/40",
      glow: "shadow-[0_4px_16px_rgba(147,51,234,0.45)]",
      textColor: "text-white",
      pillBg: "bg-purple-100 dark:bg-purple-950/60 text-purple-800 dark:text-purple-300 border-purple-200 dark:border-purple-900/60",
      accentColor: "#9333ea"
    };
  }

  // 8. DEFAULT / CELEBRACIÓN / OFERTA EXCLUSIVA
  return {
    key: "party",
    Icon: StreamlinePartyPopper,
    iconSlug: "party",
    label: "OFERTA EXCLUSIVA",
    fullLabel: cleanName || "Oferta Especial",
    gradient: "from-purple-600 via-indigo-600 to-blue-600",
    border: "border-purple-300/40",
    glow: "shadow-[0_4px_16px_rgba(147,51,234,0.45)]",
    textColor: "text-white",
    pillBg: "bg-purple-100 dark:bg-purple-950/60 text-purple-800 dark:text-purple-300 border-purple-200 dark:border-purple-900/60",
    accentColor: "#9333ea"
  };
}

/**
 * ═════════════════════════════════════════════════════════════════════════════
 * COMPONENTE EVENTBADGE: Insignias de Alto Impacto Visual Streamline
 * ═════════════════════════════════════════════════════════════════════════════
 */
export function EventBadge({
  event,
  product = null,
  variant = "card", // "card" | "pill" | "banner"
  className = "",
  size = "md"
}) {
  const config = getEventBadgeConfig(event, product);
  if (!config) return null;

  const { Icon, label, fullLabel, gradient, border, glow, textColor, pillBg } = config;

  if (variant === "card") {
    return (
      <div
        className={`absolute top-3 left-3 z-20 flex items-center gap-1.5 bg-gradient-to-r ${gradient} ${textColor} text-[11px] font-black px-3 py-1 rounded-full ${glow} border ${border} backdrop-blur-md transition-all duration-300 hover:scale-105 active:scale-95 select-none ${className}`}
      >
        <Icon size={14} stroke={2.2} className="shrink-0 drop-shadow-sm" />
        <span className="tracking-wider uppercase font-black">{label}</span>
      </div>
    );
  }

  if (variant === "pill") {
    return (
      <span
        className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-md text-[11px] font-black border transition-colors ${pillBg} ${className}`}
      >
        <Icon size={13} stroke={2} className="shrink-0" />
        <span className="truncate max-w-[170px]">{fullLabel}</span>
      </span>
    );
  }

  return (
    <span
      className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-black uppercase tracking-wider bg-gradient-to-r ${gradient} ${textColor} border ${border} ${glow} ${className}`}
    >
      <Icon size={15} stroke={2} className="shrink-0" />
      <span>{label}</span>
    </span>
  );
}
